questions.solution:
# Dictionary of student marks
students = {
    'Aarav': 82,
    'Bhavna': 67,
    'Chirag': 91,
    'Divya': 74,
    'Esha': 88
}

# Print names of students with marks > 75
for name, marks in students.items():
    if marks > 75:
        print(name)
